mapper.select:
select

from fina_survey_consignor_efficiency_model_info
where  efficiency_model_id = #{efficiencyModelId,jdbcType=BIGINT}

    and sub_service_id = #{subServiceId,jdbcType=BIGINT}


    and service_id = #{serviceId,jdbcType=BIGINT}

and area_categories_id = #{areaCategoriesId,jdbcType=INTEGER}
limit 1;

SELECT ifnull(MAX(a.days),0) FROM fina_survey_consignor_efficiency_model_info a
  where 1=1

        and a.efficiency_model_id = #{efficiencyModelId,jdbcType=BIGINT}


        and a.service_id = #{serviceId,jdbcType=BIGINT}

        SELECT
    i.days
FROM survey_consignor_efficiency_model_org o
LEFT JOIN fina_survey_consignor_efficiency_model_info i ON o.efficiency_model_id = i.efficiency_model_id
LEFT JOIN survey_consignor_efficiency_model m ON i.efficiency_model_id = m.id
WHERE o.org_id = #{param4}
AND m.type = 1

    AND i.sub_service_id = #{param1} and i.city_type = #{param3}


    AND i.service_id = #{param2} and i.city_type = #{param3}

LIMIT 1

select ifnull(t.days,0) from fina_survey_consignor_efficiency_model_info t where
    t.area_categories_id = #{areaCategoriesId,jdbcType=BIGINT}

        and t.sub_service_id = #{subServiceId,jdbcType=BIGINT}


        and t.service_id = #{serviceId,jdbcType=BIGINT}

    and t.efficiency_model_id = (
        select s.efficiency_model_id from survey_consignor_efficiency_model_org s where s.org_id = #{entrustOrgId,jdbcType=BIGINT} limit 1
    ) limit 1;

        SELECT
    IFNULL(i.days ,0) days
FROM
    fina_survey_consignor_efficiency_model_org o
    LEFT JOIN fina_survey_consignor_efficiency_model m ON o.efficiency_model_id = m.id
    LEFT JOIN fina_survey_consignor_efficiency_area_city c ON o.efficiency_model_id = c.model_id
    LEFT JOIN fina_survey_consignor_efficiency_model_info i ON c.area_categories_id = i.area_categories_id
WHERE
    o.org_id = #{param1}
    AND c.area_id = #{param3}
    AND i.service_id = #{param2}
    AND m.delete_flag = 0
	LIMIT 1;
